func run(s []int) {
	var wg sync.WaitGroup
	wg.Add(2)
	go func() {
		defer wg.Done()
		s1 := append(s, 10)
		fmt.Println("g1:", s1)
	}()
	go func() {
		defer wg.Done()
		s2 := append(s, 20)
		fmt.Println("g2:", s2)
	}()
	wg.Wait()
}

// called twice:
run(make([]int, 0, 1)) // len 0, cap 1
run(make([]int, 1))    // len 1, cap 1

listen := func(goal int) {
	defer wg.Done()
	d.cond.L.Lock()
	if d.balance < goal {
		d.cond.Wait()
	}
	fmt.Printf("$%d goal reached (balance=$%d)\n", goal, d.balance)
	d.cond.L.Unlock()
}

wg.Add(2)
go listen(10)
go listen(15)

for range 15 {
	time.Sleep(time.Millisecond)
	d.balance++
	d.cond.Broadcast()
}
wg.Wait()
